  // Remove source spans before inserting advertising. Timed captions and banners
  // remain anchored to source frames; their output times come from this schedule.
  function keptRanges(part) {
    let kept=[{start:part.start,end:part.end}];
    for(const cut of [...(state.cuts||[])].sort((a,b)=>a.start-b.start))kept=kept.flatMap(r=>cut.end<=r.start||cut.start>=r.end?[r]:[{start:r.start,end:Math.min(r.end,cut.start)},{start:Math.max(r.start,cut.end),end:r.end}].filter(x=>x.end-x.start>.0001));
    return kept;
  }
  adSchedule = function(part,clean=state.exportClean){
    const kept=keptRanges(part),length=kept.reduce((n,r)=>n+r.end-r.start,0); if(!length)return [];
    const ad=state.advertising,enabled=ad.enabled&&advertAsset&&!clean,adDuration=enabled?advertAsset.duration/ad.speed:0;
    if(enabled&&ad.profile!=='buba'&&ad.repeat&&adDuration+.099>=ad.interval)throw Error('Рекламный ролик должен быть короче интервала повторения.');
    const logical=[]; let source=0,out=0,next=enabled?(ad.profile==='buba'?length/2:ad.start):Infinity,guard=0;
    while(source<length-.0001&&guard++<1000){const remaining=length-source;if(next>=out+remaining||next<out){logical.push({kind:'source',start:out,end:out+remaining,from:source});break;}const chunk=next-out;if(chunk>0){logical.push({kind:'source',start:out,end:next,from:source});source+=chunk;}logical.push({kind:'advert',start:next,end:next+adDuration});out=next+adDuration;next=ad.profile!=='buba'&&ad.repeat?next+ad.interval:Infinity;}
    const result=[];for(const segment of logical){if(segment.kind==='advert'){result.push(segment);continue;}let pos=0;for(const r of kept){const len=r.end-r.start,a=Math.max(segment.from,pos),b=Math.min(segment.from+segment.end-segment.start,pos+len);if(b>a)result.push({kind:'source',start:segment.start+a-segment.from,end:segment.start+b-segment.from,sourceStart:r.start+a-pos,sourceEnd:r.start+b-pos});pos+=len;}}
    return result;
  };
  const selectedPart=()=>{if(previewIndex===-1)return {start:0,end:state.duration};let list=[];try{list=cuts();}catch{}return list[previewIndex??(Number($('partSelect').value)||0)]||{start:0,end:state.duration};};
