  function sourceToOutput(t,end=false){const list=outputSegments().filter(s=>s.kind==='source');for(const s of list)if(t>=s.sourceStart-.000001&&(end?t<=s.sourceEnd+.000001:t<s.sourceEnd-.000001))return s.start+Math.min(s.sourceEnd-s.sourceStart,Math.max(0,t-s.sourceStart));if(!list.length)return 0;const next=list.find(s=>s.sourceStart>t);return next?next.start:list.at(-1).end;}
  function outputToSource(t,end=false){const list=outputSegments();const s=list.find(x=>t>=x.start-.0001&&(end?t<=x.end+.0001:t<x.end))||list.at(-1);if(!s)return t;if(s.kind==='advert'){const index=list.indexOf(s);return (end?list.slice(0,index).reverse().find(x=>x.kind==='source')?.sourceEnd:list.slice(index+1).find(x=>x.kind==='source')?.sourceStart)??selectedPart().start;}return Math.min(s.sourceEnd,s.sourceStart+Math.max(0,t-s.start));}
