  const samplePanel=create('section','editor-tool');samplePanel.innerHTML='<h2>Проверить один фрагмент</h2><p class="muted">Те же макет, текст, баннеры и фон, что в полном экспорте. Готовый анализ используется повторно.</p><label class="field">Участок<select id="sampleMode"><option value="clip">Выбранная часть целиком</option><option value="range">Свой диапазон исходника</option></select></label><label class="field">Часть<select id="sampleClip"></select></label><div id="sampleRange" class="field-pair" hidden><label>Начало<input id="sampleStart" value="0.000"></label><label>Конец<input id="sampleEnd" value="10.000"></label></div><button id="renderOne" class="button primary full">Проверить один фрагмент</button><p id="sampleNote" class="muted">Остальные части не экспортируются.</p><video id="sampleResult" controls playsinline hidden></video><a id="sampleDownload" class="button secondary full" hidden download>Скачать результат</a>';
