  function jobFinished(job,type){if(type==='sample'&&job.status==='done'){const file=job.files?.find(f=>f.name?.endsWith('.mp4')&&!f.internal);if(file){$('sampleResult').src=engine+file.url;$('sampleResult').hidden=false;$('sampleDownload').href=engine+file.url;$('sampleDownload').download=file.name;$('sampleDownload').hidden=false;$('sampleNote').textContent='Готово. Просмотрите композицию и звук перед полным экспортом.';}}}

  // LLM configuration is fetched from and saved only on the engine. Secrets are
