  panes.settings.innerHTML='<h2>Модель и подключение</h2><p id="modelStatus" class="notice" role="status">Проверяем модель…</p><label class="field">Провайдер<select id="modelProvider"><option value="ollama">Ollama · локально</option><option value="openai">Совместимый API</option></select></label><label class="field">Модель<input id="modelName" placeholder="qwen3.5:9b"></label><label class="field">Адрес API<input id="modelUrl" type="url" placeholder="http://127.0.0.1:11434"></label><label class="field">API-ключ<input id="modelKey" type="password" autocomplete="new-password" placeholder="Хранится только на сервере"></label><label class="toggle-row"><span>Удалить сохранённый API-ключ</span><input id="clearModelKey" type="checkbox"></label><label class="toggle-row"><span>Разрешить отправку расшифровки и выбранных кадров внешнему API</span><input id="modelRemote" type="checkbox"></label><label class="toggle-row"><span>Модель поддерживает анализ кадров</span><input id="modelVision" type="checkbox"></label><details class="settings-details"><summary>Параметры генерации</summary><div class="field-pair"><label>Контекст<input id="modelContext" type="number" min="2048" max="32768" value="16384"></label><label>Ответ, токенов<input id="modelTokens" type="number" min="256" max="8192" value="4096"></label></div><label class="field">Тайм-аут, с<input id="modelTimeout" type="number" min="10" max="1800" value="300"></label><label class="field">Формат ответа<select id="modelFormat"><option value="json_schema">JSON Schema</option><option value="json_object">JSON Object</option></select></label></details><div class="action-pair"><button id="saveModel" class="button primary">Сохранить</button><button id="testModel" class="button secondary">Проверить связь</button></div><p class="muted">9B — более сильная локальная модель; 4B использует меньше памяти. API требует отдельного доступа. Пустое поле ключа сохраняет уже записанный ключ.</p><div class="divider"></div><h2>Общие параметры</h2><p class="muted">Тема сохраняется для этого браузера. Макет, интервалы и оформление сохраняются в проекте.</p>';
  const modelPicker=create('label','field');modelPicker.innerHTML='Установленные модели<select id="modelChoice"><option value="">Ввести имя вручную</option></select>';
  $('modelName').closest('label').before(modelPicker);
