  const speechModels=[['tiny','Tiny · быстрее'],['base','Base · обычная'],['small','Small · точнее'],['medium','Medium'],['large-v3','Large v3'],['turbo','Large v3 Turbo']];
  for(const id of ['speechModel','searchASRModel']){const chosen=$(id).value;$(id).replaceChildren(...speechModels.map(([value,label])=>new Option(label,value)));$(id).value=chosen;}
  let modelConfig={},modelLoadVersion=0,modelFormDirty=false;
