  function renderBannerControls(drawImage=true){if(!$('multiBannerControls'))return;const b=getBanner();$('multiBannerControls').hidden=!b;if(!b)return;bannerTimingHint.textContent=b.timebase==='output'?'Время показа привязано к итоговой шкале. Баннер продолжает показываться во время рекламных вставок.':'Время показа указано на итоговой шкале. Баннер остаётся на тех же исходных кадрах после вырезок; во время рекламной вставки он скрывается и возвращается вместе с основным видео.';const bounds=bannerOutputBounds(b),key={enabled:false,color:'#00ff00',similarity:.15,blend:.05,...b.chromakey};for(const [id,value]of [['multiBannerName',b.name||'Баннер'],['multiBannerStart',bounds.start.toFixed(3)],['multiBannerEnd',bounds.end.toFixed(3)],['bannerKeyColor',key.color],['bannerTolerance',key.similarity],['bannerEdge',key.blend]])if(document.activeElement!==$(id))$(id).value=value;$('multiBannerEnabled').checked=b.enabled;$('bannerKeyEnabled').checked=key.enabled;$('bannerToleranceValue').textContent=Math.round(key.similarity*100)+'%';$('bannerEdgeValue').textContent=Math.round(key.blend*100)+'%';$('bannerDuration').textContent=bounds.end>bounds.start?'Длительность на итоговой шкале: '+(bounds.end-bounds.start).toFixed(3)+' с':'Баннер не попадает в выбранную часть или удалён вместе с кадрами.';const asset=videoBanners?.info(b.asset_id);$('videoBannerControls').hidden=asset?.media_type!=='video';if(asset?.media_type==='video'){$('bannerVideoInfo').textContent=time(asset.duration,true)+' · '+(asset.audio?'со звуком':'без звука');$('bannerVideoLoop').checked=b.loop!==false;$('bannerVideoOffset').max=Math.max(0,asset.duration-.001);if(document.activeElement!==$('bannerVideoOffset'))$('bannerVideoOffset').value=b.offset||0;if(document.activeElement!==$('bannerVideoVolume'))$('bannerVideoVolume').value=b.volume||0;$('bannerVideoVolume').disabled=!asset.audio;$('bannerVideoVolumeValue').textContent=Math.round((b.volume||0)*100)+'%';}if(drawImage)drawBannerKeyPreview();}
  async function drawBannerKeyPreview(){const b=getBanner();if(!b)return;try{const image=await loadBannerImage(b);if(b!==getBanner())return;const {width,height}=mediaSize(image);if(!width||!height||(image.tagName==='VIDEO'&&image.readyState<2))return;const c=$('bannerKeyPreview'),g=c.getContext('2d'),keyed=pickingColor?image:bannerKeyImage(image,b),scale=Math.min(c.width/width,c.height/height);g.clearRect(0,0,c.width,c.height);g.drawImage(keyed,(c.width-width*scale)/2,(c.height-height*scale)/2,width*scale,height*scale);}catch(error){toast(error.message);}}
