  // Draw in the same layer order as the FFmpeg composition: background, sharp
  // source, advertisement, image overlays, captions. Cuts alter time, never media.
  const oldDraw=draw;
  draw=function(){
    videoBanners?.sync();
    const legacyEnabled=state.banner.enabled,subEnabled=state.subtitles.enabled;
    // Existing source and advertising compositing stays shared; timed text and
    // banners follow below so both legacy and new layers share ordering.
    state.banner.enabled=false;state.subtitles.enabled=false;try{oldDraw();}finally{state.banner.enabled=legacyEnabled;state.subtitles.enabled=subEnabled;}
    const inAd=previewIndex!==null&&segments[playSegment]?.kind==='advert',sourceTime=video.currentTime||0,outputTime=window.ClipPro?.outputClock?.()??(previewIndex===null?sourceToOutput(sourceTime):timelineOffset());
    if(!inAd&&legacyEnabled&&bannerImage&&sourceTime>=state.banner.start&&sourceTime<state.banner.end)fitDraw(bannerImage,state.geometry.banner);
    for(const b of window.ClipPro?.previewBanners?.()||state.banners||[]){const t=b.timebase==='output'?outputTime:sourceTime;if(!b.enabled||t<b.start||t>=b.end||(inAd&&b.timebase!=='output'))continue;const image=videoBanners?.get(b)||bannerImages.get(b.asset_id);if(image&&(image.tagName!=='VIDEO'||(image.readyState>=2&&videoBanners.timing(b).visible)))(window.ClipPro?.drawBanner?window.ClipPro.drawBanner(bannerKeyImage(image,b),b):fitDraw(bannerKeyImage(image,b),b.geometry));}
    if(!inAd&&subEnabled){const cue=activeCue(sourceTime);if(cue)drawCaptions(cue,sourceTime);}
    updateCaptionSelection();
  };
  const oldUpdateInspector=updateInspector;updateInspector=function(){const b=getBanner();if(state.layer==='editorBanner'&&b)bindBannerGeometry(b);oldUpdateInspector();if(state.layer==='editorBanner'){$('inspectorTitle').textContent='Баннер: '+(b?.name||'');$('selectionLabel').textContent='Баннер';}updateCaptionSelection();};
  const oldSelectLayer=selectLayer;selectLayer=function(layer){oldSelectLayer(layer);if(layer==='subtitles'&&route!=='subtitles'){openRoute('subtitles');return;}if(route==='design')$('layoutSettings').hidden=false;if(route==='subtitles')$('subtitleSettings').hidden=false;updateCaptionSelection();};

  function sync(){
    if(syncing)return;syncing=true;try{ensure();if(state.layer==='editorBanner'){const b=getBanner();if(b)bindBannerGeometry(b);else selectLayer('video');}
      const parts=(()=>{try{return cuts();}catch{return [];}})();for(const id of ['sampleClip','bannerPart']){const select=$(id);if(!select)continue;const chosen=previewIndex??(Number(select.value)||0);select.replaceChildren();parts.forEach((p,i)=>select.add(new Option((i+1)+' · '+time(p.start)+' — '+time(p.end),i)));select.value=String(Math.min(Math.max(0,chosen),parts.length-1));}
      const skipped=parts.filter(p=>!keptRanges(p).length).length;$('exportSkipNote').textContent=skipped?'Полностью удалены: '+skipped+' частей. Полный экспорт пропустит их. Исходные границы сохраняются; удаление можно отменить.':'';
      renderBannerList();renderBoundaries();syncCaptionControls();updateCaptionSelection();updateCaptionTimes();refreshEditorButtons();
    }finally{syncing=false;}
  }
